xlim = ax1.get_xlim()
ticks = ax1.get_xticks()
for ax in filter(None, (ax1, ax2)):
    for line in ax.get_lines():
        xd = np.asarray(line.get_xdata())
        if xd.size and np.all((xd >= xlim[0]) & (xd <= xlim[1])):
            line.set_xdata(xd + 273.15)
    for t in ax.texts:
        p = t.get_position()
        if xlim[0] <= p[0] <= xlim[1]:
            t.set_position((p[0] + 273.15, p[1]))
        xy = getattr(t, 'xy', None)
        if xy is not None and xlim[0] <= xy[0] <= xlim[1]:
            try:
                t.xy = (xy[0] + 273.15, xy[1])
            except Exception:
                pass
        s = t.get_text()
        if '°C' in s:
            num = ''.join(ch for ch in s if ch.isdigit() or ch == '.' or ch == '-')
            if num:
                try:
                    t.set_text(f'{float(num) + 273.15:.0f} K')
                except Exception:
                    pass
